import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as r,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const g=JSON.parse('{"title":"多模态（桥接）","description":"多模态能力的模型侧机制桥接 Learn LLM；本仓只保留应用侧的最小用法与一个视觉能力案例。","frontmatter":{"title":"多模态（桥接）","description":"多模态能力的模型侧机制桥接 Learn LLM；本仓只保留应用侧的最小用法与一个视觉能力案例。","domain":"tech","tags":["tech","multimodal","bridge","vision"],"navOrder":94,"topicId":"multimodal-bridge","layer":"9","status":"bridge","nodeType":"boundary","owner":"learn-ai","externalOwners":[{"site":"llm","url":"https://llm.zenheart.site/"}],"lastVerified":"2026-09-01","listed":true},"headers":[],"relativePath":"zh/tech/09-advanced/multimodal.md","filePath":"zh/tech/09-advanced/multimodal.md","lastUpdated":1788326832000}'),l={name:"zh/tech/09-advanced/multimodal.md"};function n(i,e,d,s,h,c){return r(),a("div",null,[...e[0]||(e[0]=[o('<blockquote><p><strong>所在组</strong>：进阶（桥接） ｜ <strong>上一组出口</strong>：能用发布门与版本化纪律长期运行 ｜ <strong>本页出口</strong>：知道该主题影响哪个工程决策、何时去 Learn LLM</p></blockquote><h1 id="多模态-桥接" tabindex="-1">多模态（桥接） <a class="header-anchor" href="#多模态-桥接" aria-label="Permalink to &quot;多模态（桥接）&quot;">​</a></h1><blockquote><p><strong>桥接页</strong>：多模态 tokenization（图像如何变成 token）、跨模态对齐机制、视觉编码器的推导在 <a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a>（多模态章节）。本仓只保留应用工程师需要的最小用法。</p></blockquote><h2 id="应用侧最小用法" tabindex="-1">应用侧最小用法 <a class="header-anchor" href="#应用侧最小用法" aria-label="Permalink to &quot;应用侧最小用法&quot;">​</a></h2><p>在应用里用好多模态（以视觉为例）只需要四件事：</p><ol><li><strong>消息结构</strong>：图片作为 content block（base64 / URL / Files API 三种来源）与文本并列，见 <a href="./../02-inference-interface/model-api.html">模型 API 契约</a>。</li><li><strong>成本意识</strong>：图片按尺寸折算 token，进入上下文预算——大图是真实的成本项。</li><li><strong>位置技巧</strong>：图片放在指令/问题<strong>之前</strong>效果好；多图用 <code>Image 1:</code>、<code>Image 2:</code> 标签区分。</li><li><strong>能力边界</strong>：空间推理、精确计数、人物识别是已知弱项；高风险场景必须人工复核（见 <a href="./../08-production/security.html">安全</a>）。</li></ol><p>产品化要点：多轮对话中重复引用同一图片时用 Files API 的 file_id，避免每轮重传 base64。</p><h2 id="本区页面" tabindex="-1">本区页面 <a class="header-anchor" href="#本区页面" aria-label="Permalink to &quot;本区页面&quot;">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>状态</th><th>内容</th></tr></thead><tbody><tr><td><a href="./multimodal-vision-case.html">Claude Vision 能力</a></td><td>case</td><td>Claude 视觉能力的接入细节：图片来源、限制、token 计算、提示技巧（数字以官方文档为准）</td></tr></tbody></table><h2 id="何时去-learn-llm" tabindex="-1">何时去 Learn LLM <a class="header-anchor" href="#何时去-learn-llm" aria-label="Permalink to &quot;何时去 Learn LLM&quot;">​</a></h2><ul><li>想知道图像/音频如何被切分成 token、为什么有尺寸上限 → Learn LLM 多模态 tokenization 章</li><li>想理解视觉-语言对齐训练、多模态模型的能力从哪来 → Learn LLM 跨模态机制章</li></ul><p>厂商侧的具体参数（图片张数上限、文件大小、支持格式）以<a href="https://platform.claude.com/docs/en/build-with-claude/vision" target="_blank" rel="noreferrer">官方文档</a>实时为准，本仓不维护快照数字。</p>',12)])])}const f=t(l,[["render",n]]);export{g as __pageData,f as default};
